CREATE TABLE public.courses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text UNIQUE NOT NULL, title text NOT NULL CHECK(length(title) BETWEEN 1 AND 160), description text NOT NULL DEFAULT '', category text NOT NULL DEFAULT 'AI Marketing', thumbnail text NOT NULL DEFAULT '', price_mmk integer CHECK(price_mmk>=0), access_days integer CHECK(access_days>0), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.courses TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.courses TO authenticated; GRANT ALL ON public.courses TO service_role; ALTER TABLE public.courses ENABLE ROW LEVEL SECURITY;
CREATE POLICY courses_public ON public.courses FOR SELECT TO anon,authenticated USING(status='published'); CREATE POLICY courses_admin ON public.courses FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.modules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), course_id uuid NOT NULL REFERENCES public.courses(id), title text NOT NULL, position integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.modules TO anon; GRANT ALL ON public.modules TO authenticated,service_role; ALTER TABLE public.modules ENABLE ROW LEVEL SECURITY;
CREATE POLICY modules_public ON public.modules FOR SELECT TO anon,authenticated USING(EXISTS(SELECT 1 FROM public.courses c WHERE c.id=course_id AND c.status='published')); CREATE POLICY modules_admin ON public.modules FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.lessons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), module_id uuid NOT NULL REFERENCES public.modules(id), title text NOT NULL CHECK(length(title) BETWEEN 1 AND 160), position integer NOT NULL DEFAULT 0, duration_seconds integer NOT NULL DEFAULT 0 CHECK(duration_seconds>=0), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published')), video_status text NOT NULL DEFAULT 'unconfigured' CHECK(video_status IN ('unconfigured','processing','ready','error')));
GRANT SELECT ON public.lessons TO anon; GRANT ALL ON public.lessons TO authenticated,service_role; ALTER TABLE public.lessons ENABLE ROW LEVEL SECURITY;
CREATE POLICY lessons_public ON public.lessons FOR SELECT TO anon,authenticated USING(status='published' AND EXISTS(SELECT 1 FROM public.modules m JOIN public.courses c ON c.id=m.course_id WHERE m.id=module_id AND c.status='published')); CREATE POLICY lessons_admin ON public.lessons FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), course_id uuid NOT NULL REFERENCES public.courses(id), amount_mmk integer NOT NULL CHECK(amount_mmk>=0), receipt_path text NOT NULL, reference text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), rejection_reason text, verified_by uuid REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now(), reviewed_at timestamptz);
GRANT SELECT ON public.orders TO authenticated; GRANT ALL ON public.orders TO service_role; ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY; CREATE POLICY orders_read ON public.orders FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.redeem_codes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code_hash text UNIQUE NOT NULL, course_id uuid NOT NULL REFERENCES public.courses(id), order_id uuid UNIQUE REFERENCES public.orders(id), assigned_to uuid REFERENCES public.profiles(id), expires_at timestamptz NOT NULL, redeemed_by uuid REFERENCES public.profiles(id), redeemed_at timestamptz, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.redeem_codes TO service_role; ALTER TABLE public.redeem_codes ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.enrollments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), course_id uuid NOT NULL REFERENCES public.courses(id), source_code uuid UNIQUE REFERENCES public.redeem_codes(id), starts_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, revoked_at timestamptz, UNIQUE(user_id,course_id));
GRANT SELECT ON public.enrollments TO authenticated; GRANT ALL ON public.enrollments TO service_role; ALTER TABLE public.enrollments ENABLE ROW LEVEL SECURITY; CREATE POLICY enrollments_read ON public.enrollments FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.registered_devices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), token_hash text NOT NULL, session_id text NOT NULL, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), last_seen timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, UNIQUE(user_id,token_hash,session_id));
GRANT SELECT ON public.registered_devices TO authenticated; GRANT ALL ON public.registered_devices TO service_role; ALTER TABLE public.registered_devices ENABLE ROW LEVEL SECURITY; CREATE POLICY devices_read ON public.registered_devices FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.lesson_progress (user_id uuid NOT NULL REFERENCES public.profiles(id), lesson_id uuid NOT NULL REFERENCES public.lessons(id), position_seconds integer NOT NULL DEFAULT 0 CHECK(position_seconds>=0), completed boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,lesson_id));
GRANT SELECT ON public.lesson_progress TO authenticated; GRANT ALL ON public.lesson_progress TO service_role; ALTER TABLE public.lesson_progress ENABLE ROW LEVEL SECURITY; CREATE POLICY progress_read ON public.lesson_progress FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.cms_sections (key text PRIMARY KEY, title text NOT NULL DEFAULT '', body text NOT NULL DEFAULT '', image text NOT NULL DEFAULT '', position integer NOT NULL DEFAULT 0, published boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.cms_sections TO anon; GRANT ALL ON public.cms_sections TO authenticated,service_role; ALTER TABLE public.cms_sections ENABLE ROW LEVEL SECURITY; CREATE POLICY cms_public ON public.cms_sections FOR SELECT TO anon,authenticated USING(published); CREATE POLICY cms_admin ON public.cms_sections FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.academy_settings (key text PRIMARY KEY, value text NOT NULL DEFAULT '', published boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.academy_settings TO anon; GRANT ALL ON public.academy_settings TO authenticated,service_role; ALTER TABLE public.academy_settings ENABLE ROW LEVEL SECURITY; CREATE POLICY settings_public ON public.academy_settings FOR SELECT TO anon,authenticated USING(published); CREATE POLICY settings_admin ON public.academy_settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES public.profiles(id), action text NOT NULL, entity_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_events TO authenticated; GRANT ALL ON public.audit_events TO service_role; ALTER TABLE public.audit_events ENABLE ROW LEVEL SECURITY; CREATE POLICY audit_admin ON public.audit_events FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE INDEX orders_user_idx ON public.orders(user_id); CREATE INDEX orders_status_idx ON public.orders(status); CREATE INDEX enrollments_user_idx ON public.enrollments(user_id); CREATE INDEX devices_user_idx ON public.registered_devices(user_id); CREATE INDEX modules_course_idx ON public.modules(course_id); CREATE INDEX lessons_module_idx ON public.lessons(module_id);
CREATE FUNCTION public.lms_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.audit_events(actor_id,action,entity_id) VALUES(auth.uid(),TG_TABLE_NAME||'.'||lower(TG_OP),COALESCE(to_jsonb(NEW)->>'id',to_jsonb(NEW)->>'key','')); RETURN NEW; END $$;
CREATE TRIGGER courses_audit AFTER INSERT OR UPDATE ON public.courses FOR EACH ROW EXECUTE FUNCTION public.lms_audit(); CREATE TRIGGER modules_audit AFTER INSERT OR UPDATE ON public.modules FOR EACH ROW EXECUTE FUNCTION public.lms_audit(); CREATE TRIGGER lessons_audit AFTER INSERT OR UPDATE ON public.lessons FOR EACH ROW EXECUTE FUNCTION public.lms_audit(); CREATE TRIGGER cms_audit AFTER INSERT OR UPDATE ON public.cms_sections FOR EACH ROW EXECUTE FUNCTION public.lms_audit(); CREATE TRIGGER settings_audit AFTER INSERT OR UPDATE ON public.academy_settings FOR EACH ROW EXECUTE FUNCTION public.lms_audit();
CREATE FUNCTION public.lms_register_device(p_hash text,p_session text,p_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.registered_devices; n integer; BEGIN IF auth.uid() IS NULL OR length(p_hash)<>64 OR length(p_session)<1 OR length(p_name)>100 THEN RAISE EXCEPTION 'Invalid device registration'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(auth.uid()::text,0)); SELECT * INTO d FROM public.registered_devices WHERE user_id=auth.uid() AND token_hash=p_hash AND session_id=p_session FOR UPDATE; IF FOUND THEN IF d.revoked_at IS NOT NULL THEN RAISE EXCEPTION 'This device session was removed. Sign out and sign in again.'; END IF; UPDATE public.registered_devices SET last_seen=now() WHERE id=d.id; RETURN d.id; END IF; SELECT count(*) INTO n FROM public.registered_devices WHERE user_id=auth.uid() AND revoked_at IS NULL; IF n>=2 THEN RAISE EXCEPTION 'Two devices are already registered. Remove a device before continuing.'; END IF; INSERT INTO public.registered_devices(user_id,token_hash,session_id,name) VALUES(auth.uid(),p_hash,p_session,p_name) RETURNING * INTO d; RETURN d.id; END $$;
REVOKE ALL ON FUNCTION public.lms_register_device(text,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.lms_register_device(text,text,text) TO authenticated;
CREATE FUNCTION public.lms_submit_order(p_course uuid,p_receipt text,p_reference text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.courses; result uuid; BEGIN IF auth.uid() IS NULL OR length(p_reference)>200 OR p_receipt NOT LIKE auth.uid()::text||'/%' THEN RAISE EXCEPTION 'Invalid payment submission'; END IF; SELECT * INTO c FROM public.courses WHERE id=p_course AND status='published'; IF NOT FOUND OR c.price_mmk IS NULL OR c.access_days IS NULL OR NOT EXISTS(SELECT 1 FROM public.academy_settings WHERE key='payment_instructions' AND published AND length(value)>0) THEN RAISE EXCEPTION 'Payment details are not available yet'; END IF; INSERT INTO public.orders(user_id,course_id,amount_mmk,receipt_path,reference) VALUES(auth.uid(),c.id,c.price_mmk,p_receipt,p_reference) RETURNING id INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.lms_submit_order(uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.lms_submit_order(uuid,text,text) TO authenticated;
CREATE FUNCTION public.lms_review_order(p_order uuid,p_approve boolean,p_reason text,p_hash text,p_expires timestamptz) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders; result uuid; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin access required'; END IF; SELECT * INTO o FROM public.orders WHERE id=p_order FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Payment not found'; END IF; IF o.status='approved' THEN SELECT id INTO result FROM public.redeem_codes WHERE order_id=o.id; RETURN result; END IF; IF o.status<>'pending' THEN RAISE EXCEPTION 'Payment already reviewed'; END IF; IF p_approve THEN IF length(p_hash)<>64 OR p_expires<=now() THEN RAISE EXCEPTION 'Valid code expiry required'; END IF; INSERT INTO public.redeem_codes(code_hash,course_id,order_id,assigned_to,expires_at) VALUES(p_hash,o.course_id,o.id,o.user_id,p_expires) RETURNING id INTO result; ELSE IF length(trim(COALESCE(p_reason,'')))=0 OR length(p_reason)>1000 THEN RAISE EXCEPTION 'A rejection reason is required'; END IF; END IF; UPDATE public.orders SET status=CASE WHEN p_approve THEN 'approved' ELSE 'rejected' END,rejection_reason=CASE WHEN p_approve THEN NULL ELSE p_reason END,verified_by=auth.uid(),reviewed_at=now() WHERE id=o.id; INSERT INTO public.audit_events(actor_id,action,entity_id) VALUES(auth.uid(),CASE WHEN p_approve THEN 'payment.approved' ELSE 'payment.rejected' END,o.id::text); RETURN result; END $$;
REVOKE ALL ON FUNCTION public.lms_review_order(uuid,boolean,text,text,timestamptz) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.lms_review_order(uuid,boolean,text,text,timestamptz) TO authenticated;
CREATE FUNCTION public.lms_redeem(p_hash text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.redeem_codes; days integer; result uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; SELECT * INTO c FROM public.redeem_codes WHERE code_hash=p_hash FOR UPDATE; IF NOT FOUND OR c.expires_at<=now() OR c.revoked_at IS NOT NULL OR c.redeemed_at IS NOT NULL OR (c.assigned_to IS NOT NULL AND c.assigned_to<>auth.uid()) THEN RAISE EXCEPTION 'Code is invalid, expired, or already used'; END IF; SELECT access_days INTO days FROM public.courses WHERE id=c.course_id AND status='published'; IF days IS NULL THEN RAISE EXCEPTION 'Course access is not configured'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(auth.uid()::text||c.course_id::text,0)); IF EXISTS(SELECT 1 FROM public.enrollments WHERE user_id=auth.uid() AND course_id=c.course_id AND revoked_at IS NULL AND expires_at>now()) THEN RAISE EXCEPTION 'You already have active access to this course'; END IF; INSERT INTO public.enrollments(user_id,course_id,source_code,expires_at) VALUES(auth.uid(),c.course_id,c.id,now()+make_interval(days=>days)) ON CONFLICT(user_id,course_id) DO UPDATE SET source_code=c.id,starts_at=now(),expires_at=now()+make_interval(days=>days),revoked_at=NULL RETURNING id INTO result; UPDATE public.redeem_codes SET redeemed_by=auth.uid(),redeemed_at=now() WHERE id=c.id; INSERT INTO public.audit_events(actor_id,action,entity_id) VALUES(auth.uid(),'course.redeemed',c.course_id::text); RETURN result; END $$;
REVOKE ALL ON FUNCTION public.lms_redeem(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.lms_redeem(text) TO authenticated;
CREATE FUNCTION public.lms_revoke_device(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; UPDATE public.registered_devices SET revoked_at=now() WHERE id=p_id AND (user_id=auth.uid() OR public.has_role(auth.uid(),'admin')); IF NOT FOUND THEN RAISE EXCEPTION 'Device not found'; END IF; INSERT INTO public.audit_events(actor_id,action,entity_id) VALUES(auth.uid(),'device.revoked',p_id::text); END $$;
REVOKE ALL ON FUNCTION public.lms_revoke_device(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.lms_revoke_device(uuid) TO authenticated;
CREATE FUNCTION public.lms_save_progress(p_lesson uuid,p_position integer,p_completed boolean,p_hash text,p_session text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l public.lessons; BEGIN IF NOT EXISTS(SELECT 1 FROM public.registered_devices WHERE user_id=auth.uid() AND token_hash=p_hash AND session_id=p_session AND revoked_at IS NULL) THEN RAISE EXCEPTION 'Active device required'; END IF; SELECT * INTO l FROM public.lessons WHERE id=p_lesson AND status='published'; IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.modules m JOIN public.enrollments e ON e.course_id=m.course_id WHERE m.id=l.module_id AND e.user_id=auth.uid() AND e.revoked_at IS NULL AND e.expires_at>now()) THEN RAISE EXCEPTION 'Active course access required'; END IF; IF p_position<0 OR p_position>l.duration_seconds THEN RAISE EXCEPTION 'Invalid playback position'; END IF; INSERT INTO public.lesson_progress(user_id,lesson_id,position_seconds,completed) VALUES(auth.uid(),p_lesson,p_position,p_completed AND p_position>=l.duration_seconds*0.9 AND l.duration_seconds>0) ON CONFLICT(user_id,lesson_id) DO UPDATE SET position_seconds=p_position,completed=lesson_progress.completed OR EXCLUDED.completed,updated_at=now(); END $$;
REVOKE ALL ON FUNCTION public.lms_save_progress(uuid,integer,boolean,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.lms_save_progress(uuid,integer,boolean,text,text) TO authenticated;